package com.wheelwright.evidence.v2.portfolio;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
import static org.assertj.core.api.Assertions.*;

class PortfolioTerminalSettlementTest {
 ObjectNode contract(){var c=PortfolioShareCallShapeTest.fixture("100","100","1");var t=(ObjectNode)c.at("/composition/children/1/terms");t.putNull("multiplier").put("qualification","INCOMPLETE").put("payoffApplicability","UNKNOWN").put("exerciseStyle","AMERICAN");var definition=obj().put("kind","REFERENCE_SOURCE").put("provider","TASTYTRADE").put("reference","urn:wheelwright:tastytrade:option-definition:sha256:"+"a".repeat(64)+":item:0").putNull("observedAt").put("qualification","VERIFIED_REFERENCE");var chain=definition.deepCopy().put("reference","urn:wheelwright:tastytrade:option-chain:sha256:"+"b".repeat(64)+":item:0");var raw=obj().put("instrument-type","Equity Option").put("option-chain-type","Standard").put("exercise-style","American").put("root-symbol","ABC").put("underlying-symbol","ABC").put("strike-price","10").put("shares-per-contract",100);PortfolioTerminalSettlement.declared(t,raw,definition);t.set("evidence",array().add(definition).add(chain));PortfolioTerminalSettlement.qualify(t);return c;}
 @Test void exerciseRightsRemainTerminalOnlyEvenWithKnownBasis(){var c=contract();for(var leaf:leaves(c.path("composition"))){var basis=(ObjectNode)leaf.at("/allocation/basis");basis.put("value","10").put("unit","MONEY").put("currency","USD").put("status","QUALIFIED");}var p=PortfolioMath.payoff(c,Instant.parse("2026-10-29T16:00:00Z"));assertThat(p.path("status").asText()).isEqualTo("QUALIFIED");assertThat(p.at("/geometry/valueKind").asText()).isEqualTo("TERMINAL_VALUE");assertThat(p.at("/geometry/breakEvenPrices")).isEmpty();assertThat(c.at("/composition/children/1/terms/multiplier").isNull()).isTrue();}
 @Test void sourceProfileAndPhysicalExerciseDependenciesAreIndependentlyRequired(){for(String defect:List.of("profile","strikeUnit","consideration","currency","quantity","cash","mixed","underlying","adjusted","style","expiry","definition","chain","spec","conflict")){var c=contract();var t=(ObjectNode)c.at("/composition/children/1/terms");var p=(ObjectNode)t.path("terminalSettlement");switch(defect){case "profile"->p.put("profile","GUESSED");case "strikeUnit"->p.put("strikeUnit","UNKNOWN");case "consideration"->p.put("consideration","UNKNOWN");case "currency"->t.put("currency","EUR");case "quantity"->((ObjectNode)t.at("/deliverable/0")).put("quantity","50");case "cash"->((ObjectNode)t.at("/deliverable/0")).put("kind","CASH");case "mixed"->((ArrayNode)t.path("deliverable")).add(obj().put("kind","CASH").put("quantity","1"));case "underlying"->((ObjectNode)t.at("/deliverable/0/instrument")).put("href","/v2/instruments/OTHER");case "adjusted"->t.put("adjustment","ADJUSTED");case "style"->t.put("exerciseStyle","UNKNOWN");case "expiry"->t.putNull("expiration");case "definition"->((ArrayNode)t.path("evidence")).remove(0);case "chain"->((ArrayNode)t.path("evidence")).remove(1);case "spec"->p.set("evidence",array());default->t.put("qualification","CONFLICT");}assertThat(PortfolioTerminalSettlement.quantity(t)).as(defect).isNull();assertThat(PortfolioMath.terminalPayoff(c,Instant.now()).path("status").asText()).as(defect).isNotEqualTo("QUALIFIED");}}
 @Test void referenceCompositionIsIdempotentAndRevokesTerminalClaimOnContradiction(){var t=(ObjectNode)contract().at("/composition/children/1/terms");assertThat(PortfolioReferenceTerms.combine(t,t.deepCopy())).isEqualTo(t);var changed=t.deepCopy();((ObjectNode)changed.at("/deliverable/0")).put("quantity","50");var merged=PortfolioReferenceTerms.combine(t,changed);assertThat(merged.path("qualification").asText()).isEqualTo("CONFLICT");assertThat(merged.at("/terminalSettlement/status").asText()).isEqualTo("CONFLICT");assertThat(PortfolioTerminalSettlement.quantity(merged)).isNull();}
}
